mapper.select:
/* isry.drmgs.dashboard.mapper.DashboardMapper.selectLinkCnt - HeeSung Yoon */ SELECT COUNT(*) AS CNT FROM SEB400 T1, SEB420 T2 WHERE T1.SRVC_PVSN_RQST_NO = T2.SRVC_PVSN_RQST_NO AND T1.RCPT_UNT_TASKWK_SE_CD = #{RCPT_UNT_TASKWK_SE_CD} AND T2.RCPT_SE_CD = #{RCPT_SE_CD} AND T2.RCPT_SN = (SELECT MAX(RCPT_SN) FROM SEB420 WHERE SRVC_PVSN_RQST_NO = T2.SRVC_PVSN_RQST_NO)
AND T1.LINK_TYPE_SE_CD = #{LINK_TYPE_SE_CD}
AND T1.LINK_TYPE_SE_CD NOT IN ('05','06')
AND EXISTS (SELECT 1 FROM SEB400 WHERE SRVC_PVSN_RQST_NO <> T1.SRVC_PVSN_RQST_NO AND RCPT_UNT_TASKWK_SE_CD = T1.RCPT_UNT_TASKWK_SE_CD AND LINK_TYPE_SE_CD = T1.LINK_TYPE_SE_CD AND RQST_TRPR_INFO_NO = T1.RQST_TRPR_INFO_NO AND CLINT_NO = T1.CLINT_NO AND RCPT_SE_CD = '21')
